def max_gap(werte):
    if len(werte) < 2:
        return 0

    sortierte_werte = sorted(werte)
    max_diff = 0

    for i in range(len(sortierte_werte) - 1):
        diff = sortierte_werte[i+1] - sortierte_werte[i]
        if diff > max_diff:
            max_diff = diff

    return max_diff
